"""An LRU cache with per-entry time-to-live (TTL).

An entry is EXPIRED when ``now() - written_at >= ttl_seconds``. Expired
entries are removed lazily: a ``get`` that finds one deletes it without
touching recency ordering, and a ``put`` that needs room purges every
expired entry before evicting the least-recently-used live entry.
"""

import time
from collections import OrderedDict


class Cache:
    def __init__(self, capacity, ttl_seconds, now=time.monotonic):
        self._capacity = capacity
        self._ttl = ttl_seconds
        self._now = now
        # key -> (value, written_at); iteration order is LRU -> MRU.
        self._entries = OrderedDict()

    def _is_expired(self, written_at, t):
        return t - written_at >= self._ttl

    def _purge_expired(self, t):
        for key in [k for k, (_, written_at) in self._entries.items()
                    if self._is_expired(written_at, t)]:
            del self._entries[key]

    def put(self, key, value):
        t = self._now()
        if self._capacity <= 0:
            return
        if key in self._entries:
            # Update: new value, TTL clock resets, becomes most-recently-used.
            self._entries[key] = (value, t)
            self._entries.move_to_end(key)
            return
        if len(self._entries) >= self._capacity:
            # Expired entries never occupy capacity: drop them all first.
            self._purge_expired(t)
            if len(self._entries) >= self._capacity:
                # Still full: evict the least-recently-used live entry.
                self._entries.popitem(last=False)
        self._entries[key] = (value, t)

    def get(self, key):
        t = self._now()
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, written_at = entry
        if self._is_expired(written_at, t):
            # Expired: remove it, but do NOT change recency ordering.
            del self._entries[key]
            return None
        self._entries.move_to_end(key)
        return value

    def __len__(self):
        self._purge_expired(self._now())
        return len(self._entries)

    def keys(self):
        self._purge_expired(self._now())
        return list(self._entries)
